__disc("api/actor/1600983",{"cik":1600983,"name":"Knightscope, Inc.","regime":"10-K","filings":[{"acc":"0001410578-22-000372","form":"10-Q","date":"2022-03-14","url":"https://www.sec.gov/Archives/edgar/data/1600983/000141057822000372/tmb-20210930x10q.htm","rf_words":7508,"rf_ai":null,"rf_method":null,"txt":"4a08316d2a2387f3","coded":true,"n_ai_harm":1,"n_passages":1},{"acc":"0001410578-22-000800","form":"10-K","date":"2022-03-31","url":"https://www.sec.gov/Archives/edgar/data/1600983/000141057822000800/tmb-20211231x10k.htm","rf_words":7507,"rf_ai":null,"rf_method":null,"txt":"6ae829a67110072d","coded":true,"n_ai_harm":1,"n_passages":1},{"acc":"0001410578-22-001693","form":"10-Q","date":"2022-05-16","url":"https://www.sec.gov/Archives/edgar/data/1600983/000141057822001693/tmb-20220331x10q.htm","rf_words":120,"rf_ai":null,"rf_method":null,"txt":"4aefae2b77894ff8","coded":true,"n_ai_harm":0,"n_passages":0},{"acc":"0001410578-22-002618","form":"10-Q","date":"2022-08-15","url":"https://www.sec.gov/Archives/edgar/data/1600983/000141057822002618/tmb-20220630x10q.htm","rf_words":120,"rf_ai":null,"rf_method":null,"txt":"4aefae2b77894ff8","coded":true,"n_ai_harm":0,"n_passages":0},{"acc":"0001410578-22-003412","form":"10-Q","date":"2022-11-14","url":"https://www.sec.gov/Archives/edgar/data/1600983/000141057822003412/tmb-20220930x10q.htm","rf_words":523,"rf_ai":null,"rf_method":null,"txt":"06bee37aa2b946df","coded":true,"n_ai_harm":0,"n_passages":0},{"acc":"0001410578-23-000578","form":"10-K","date":"2023-03-31","url":"https://www.sec.gov/Archives/edgar/data/1600983/000141057823000578/tmb-20221231x10k.htm","rf_words":8437,"rf_ai":null,"rf_method":null,"txt":"d5d2c1ec7e621b57","coded":true,"n_ai_harm":1,"n_passages":1},{"acc":"0001410578-23-001106","form":"10-Q","date":"2023-05-12","url":"https://www.sec.gov/Archives/edgar/data/1600983/000141057823001106/tmb-20230331x10q.htm","rf_words":120,"rf_ai":null,"rf_method":null,"txt":"185e923fd0a8ed8a","coded":true,"n_ai_harm":0,"n_passages":0},{"acc":"0001410578-23-001838","form":"10-Q","date":"2023-08-14","url":"https://www.sec.gov/Archives/edgar/data/1600983/000141057823001838/tmb-20230630x10q.htm","rf_words":120,"rf_ai":null,"rf_method":null,"txt":"185e923fd0a8ed8a","coded":true,"n_ai_harm":0,"n_passages":0},{"acc":"0001410578-23-002349","form":"10-Q","date":"2023-11-13","url":"https://www.sec.gov/Archives/edgar/data/1600983/000141057823002349/tmb-20230930x10q.htm","rf_words":120,"rf_ai":null,"rf_method":null,"txt":"185e923fd0a8ed8a","coded":true,"n_ai_harm":0,"n_passages":0},{"acc":"0001104659-24-025214","form":"8-K","date":"2024-02-20","url":"https://www.sec.gov/Archives/edgar/data/1600983/000110465924025214/tm246663d1_8k.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"0ddcbc0d1385b5ab","coded":true,"n_ai_harm":0,"n_passages":3},{"acc":"0001104659-24-029611","form":"8-K","date":"2024-03-01","url":"https://www.sec.gov/Archives/edgar/data/1600983/000110465924029611/tm247617d1_8k.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"ac941b8abfc98e43","coded":true,"n_ai_harm":1,"n_passages":2},{"acc":"0001104659-24-034500","form":"8-K","date":"2024-03-14","url":"https://www.sec.gov/Archives/edgar/data/1600983/000110465924034500/tm248838d1_8k.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"80ebe28908251ffa","coded":true,"n_ai_harm":0,"n_passages":7},{"acc":"0001410578-24-000417","form":"10-K","date":"2024-04-01","url":"https://www.sec.gov/Archives/edgar/data/1600983/000141057824000417/tmb-20231231x10k.htm","rf_words":14245,"rf_ai":null,"rf_method":null,"txt":"087bf8d482d03b87","coded":true,"n_ai_harm":1,"n_passages":2},{"acc":"0001104659-24-042212","form":"8-K","date":"2024-04-02","url":"https://www.sec.gov/Archives/edgar/data/1600983/000110465924042212/tm2410412d1_8k.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"b9eac2bafdfeb7c7","coded":true,"n_ai_harm":0,"n_passages":1},{"acc":"0001410578-24-000903","form":"10-Q","date":"2024-05-16","url":"https://www.sec.gov/Archives/edgar/data/1600983/000141057824000903/tmb-20240331x10q.htm","rf_words":100,"rf_ai":null,"rf_method":null,"txt":"c2fa77612de0bd52","coded":true,"n_ai_harm":0,"n_passages":0},{"acc":"0001558370-24-012268","form":"10-Q","date":"2024-08-14","url":"https://www.sec.gov/Archives/edgar/data/1600983/000155837024012268/kscp-20240630x10q.htm","rf_words":93,"rf_ai":null,"rf_method":null,"txt":"cde4e9a9bbd49537","coded":true,"n_ai_harm":0,"n_passages":0},{"acc":"0001558370-24-015747","form":"10-Q","date":"2024-11-14","url":"https://www.sec.gov/Archives/edgar/data/1600983/000155837024015747/kscp-20240930x10q.htm","rf_words":93,"rf_ai":null,"rf_method":null,"txt":"cde4e9a9bbd49537","coded":true,"n_ai_harm":0,"n_passages":0},{"acc":"0001104659-24-122131","form":"8-K","date":"2024-11-22","url":"https://www.sec.gov/Archives/edgar/data/1600983/000110465924122131/tm2429235d1_8k.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"6e48f1f180253719","coded":true,"n_ai_harm":0,"n_passages":2},{"acc":"0001104659-25-022699","form":"8-K","date":"2025-03-12","url":"https://www.sec.gov/Archives/edgar/data/1600983/000110465925022699/tm258926d1_8k.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"f8acf629770b6e26","coded":true,"n_ai_harm":0,"n_passages":3},{"acc":"0001558370-25-004171","form":"10-K","date":"2025-03-31","url":"https://www.sec.gov/Archives/edgar/data/1600983/000155837025004171/kscp-20241231x10k.htm","rf_words":13920,"rf_ai":null,"rf_method":null,"txt":"1e9f69ee1954b62c","coded":true,"n_ai_harm":1,"n_passages":2},{"acc":"0001104659-25-029917","form":"8-K","date":"2025-03-31","url":"https://www.sec.gov/Archives/edgar/data/1600983/000110465925029917/tm2510385d3_8k.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"0568e08a7c52337d","coded":true,"n_ai_harm":0,"n_passages":2},{"acc":"0001104659-25-034664","form":"8-K","date":"2025-04-14","url":"https://www.sec.gov/Archives/edgar/data/1600983/000110465925034664/tm2512231d1_8k.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"9ef694175943b099","coded":true,"n_ai_harm":0,"n_passages":2},{"acc":"0001558370-25-007781","form":"10-Q","date":"2025-05-14","url":"https://www.sec.gov/Archives/edgar/data/1600983/000155837025007781/kscp-20250331x10q.htm","rf_words":102,"rf_ai":null,"rf_method":null,"txt":"8144ebf7f454ab4f","coded":true,"n_ai_harm":0,"n_passages":0},{"acc":"0001558370-25-011247","form":"10-Q","date":"2025-08-12","url":"https://www.sec.gov/Archives/edgar/data/1600983/000155837025011247/kscp-20250630x10q.htm","rf_words":102,"rf_ai":null,"rf_method":null,"txt":"8144ebf7f454ab4f","coded":true,"n_ai_harm":0,"n_passages":0},{"acc":"0001104659-25-110518","form":"10-Q","date":"2025-11-12","url":"https://www.sec.gov/Archives/edgar/data/1600983/000110465925110518/kscp-20250930x10q.htm","rf_words":102,"rf_ai":null,"rf_method":null,"txt":"8144ebf7f454ab4f","coded":true,"n_ai_harm":0,"n_passages":0},{"acc":"0001104659-26-022476","form":"8-K","date":"2026-03-03","url":"https://www.sec.gov/Archives/edgar/data/1600983/000110465926022476/tm267594d1_8k.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"c79f455305274f37","coded":true,"n_ai_harm":1,"n_passages":6},{"acc":"0001104659-26-036240","form":"10-K","date":"2026-03-27","url":"https://www.sec.gov/Archives/edgar/data/1600983/000110465926036240/kscp-20251231x10k.htm","rf_words":14164,"rf_ai":null,"rf_method":null,"txt":"69baa11514f295d5","coded":true,"n_ai_harm":1,"n_passages":3},{"acc":"0001104659-26-062505","form":"10-Q","date":"2026-05-15","url":"https://www.sec.gov/Archives/edgar/data/1600983/000110465926062505/kscp-20260331x10q.htm","rf_words":102,"rf_ai":null,"rf_method":null,"txt":"a91731699094db4a","coded":true,"n_ai_harm":0,"n_passages":0},{"acc":"0001104659-26-094868","form":"8-K","date":"2026-08-12","url":"https://www.sec.gov/Archives/edgar/data/1600983/000110465926094868/kscp-20260812x8k.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"0238ec73fcaea8ea","coded":true,"n_ai_harm":0,"n_passages":1},{"acc":"0001104659-26-094859","form":"10-Q","date":"2026-08-12","url":"https://www.sec.gov/Archives/edgar/data/1600983/000110465926094859/kscp-20260630x10q.htm","rf_words":109,"rf_ai":null,"rf_method":null,"txt":"060796b60e3ed617","coded":true,"n_ai_harm":0,"n_passages":0},{"acc":"0001104659-26-109484","form":"8-K","date":"2026-09-22","url":"https://www.sec.gov/Archives/edgar/data/1600983/000110465926109484/kscp-20260922x8k.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"5da1a9e66f3ac47f","coded":true,"n_ai_harm":0,"n_passages":2}],"passages":[{"id":"1600983-532f154b87","kind":"annual","source":null,"discloses":"ai_harm","mit":["7.3"],"primary":"7.3","status":"elsewhere","harm":["Physical (injury)"],"layers":["capability"],"whose":["own","others"],"relation":["within_purpose"],"misuse_by":[],"subjects":[],"text":"Nonetheless, real-life environments, especially those in crowded areas, are unpredictable and situations may arise in which the ASRs may not perform as intended. Infrequent, but highly publicized incidents of autonomous vehicle and human interactions have focused consumer attention on the safety of such systems. We continuously test the ASRs in a number of unpredictable environments and continue to improve each model’s obstacle-sensing and crash-prevention technology.","ev":{"status":"Infrequent, but highly publicized incidents of autonomous vehicle and human interactions have focused consumer attention on the safety of such systems","mit:7.3":"situations may arise in which the ASRs may not perform as intended","harm:Physical (injury)":"Infrequent, but highly publicized incidents of autonomous vehicle and human interactions have focused consumer attention on the safety of such systems.","layer:capability":"situations may arise in which the ASRs may not perform as intended","whose:own":"We continuously test the ASRs in a number of unpredictable environments","whose:others":"Infrequent, but highly publicized incidents of autonomous vehicle and human interactions","relation:within_purpose":"We continuously test the ASRs in a number of unpredictable environments"},"rev":null,"harm_quote":"situations may arise in which the ASRs may not perform as intended","status_quote":"Infrequent, but highly publicized incidents of autonomous vehicle and human interactions have focused consumer attention on the safety of such systems","reports":["0001410578-22-000372","0001410578-22-000800","0001410578-23-000578"],"forms":{"10-K":2,"10-Q":1},"first":"2022-03-14","last":"2023-03-31","end":"2024-04-01"},{"id":"1600983-4d53715506","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"As we continue to expand into other foreign countries and jurisdictions, we may be subject to additional laws and regulations that may affect how we conduct business. The regulatory framework for AI is rapidly evolving as many federal, state and foreign government bodies and agencies have introduced or are currently considering additional laws and regulations. Additionally, existing laws and regulations may be interpreted in ways that would affect the operation of our AI technologies. As a result, implementation standards and enforcement practices are likely to remain uncertain for the foreseeable future, and we cannot yet determine the impact future laws, regulations, standards, or market perception of their requirements may have on our business and may not always be able to anticipate how to respond to these laws or regulations. Already, certain existing legal regimes (e.g., relating to data privacy) regulate certain aspects of AI, and new laws regulating AI are expected to enter into force in the United States and the EU in 2024. In the United States, the Biden administration issued a broad Executive Order on the Safe, Secure, and Trustworthy Development and Use of Artificial Intelligence (the “2023 AI Order”), that sets out principles intended to guide AI design and deployment for the public and private sector and signals the increase in governmental involvement and regulation over AI. The 2023 AI Order established certain new requirements for the training, testing and cybersecurity of sophisticated AI models and large-scale compute centers used to train AI models. The 2023 AI Order also instructed several other federal agencies to promulgate additional regulations within specific timeframes from the date of the 2023 AI Order regarding the use and development of AI. Already, agencies such as the Department of Commerce and the FTC have issued proposed rules governing the use and development of AI. Legislation related to AI has also been introduced at the federal level and is advancing at the state level. For example, the California Privacy Protection Agency is currently in the process of finalizing regulations under the CCPA regarding the use of automated decision-making. Such additional regulations may impact our ability to develop, use and commercialize AI technologies in the future. 21 Table of Contents In Europe, on March 13, 2024, the European Parliament passed the EU Artificial Intelligence Act (“EU AI Act”) which establishes a comprehensive, risk-based governance framework for artificial intelligence in the EU market. The EU AI Act will enter into force twenty days after its publication in the Official Journal of the EU and will be fully effective two years later. The EU AI Act will apply to companies that develop, use and/or provide AI in the EU and includes requirements around transparency, conformity assessments and monitoring, risk assessments, human oversight, security, accuracy, general purpose AI and foundation models, and proposes fines for breach of up to 7% of worldwide annual turnover. In addition, on September 28, 2022, the European Commission proposed two Directives seeking to establish a harmonized civil liability regime for AI in the EU, in order to facilitate civil claims in respect of harm caused by AI and to include AI-enabled products within the scope of the EU’s existing strict product liability regime. Once fully applicable, the EU AI Act and the Liability Directives will have a material impact on the way AI is regulated in the EU. Further, in Europe we are subject to the GDPR, which regulates our use of personal data for automated decision making including individual profiling that results in a legal or similarly significant effect on an individual and provides rights to individuals in respect of that automated decision making. Recent case law from the CJEU has taken an expansive view of the scope of the GDPR’s requirements around automated decision making and introduced uncertainty in the interpretation of these rules. Specifically, the CJEU has expanded the scope for automated decision making under the GDPR by finding that automated decision-making activities can fall within the GDPR’s restrictions on those activities even if the required legal or similarly significant effect for the individual is carried out by a third party. The EU AI Act, and developing interpretation and application of the GDPR in respect of automated decision making, together with developing guidance and/or decisions in this area, may affect our use of AI and our ability to provide, improve or commercialize our services, require additional compliance measures and changes to our operations and processes, result in increased compliance costs and potential increases in civil claims against us, and could adversely affect our business, operations and financial condition. It is possible that further new laws and regulations will be adopted in the United States and in other non-U.S. jurisdictions, or that existing laws and regulations, including competition and antitrust laws, may be interpreted in ways that would limit our ability to use AI for our business, or require us to change the way we use AI in a manner that negatively affects [the performance of our products, services, and business and the way in which we use AI. We may need to expend resources to adjust our products or services in certain jurisdictions if the laws, regulations, or decisions are not consistent across jurisdictions. Further, the cost to comply with such laws, regulations, or decisions and/or guidance interpreting existing laws, could be significant and would increase our operating expenses (such as by imposing additional reporting obligations regarding our use of AI). Such an increase in operating expenses, as well as any actual or perceived failure to comply with such laws and regulations, could adversely affect our business, financial condition and results of operations.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001410578-24-000417"],"forms":{"10-K":1},"first":"2024-04-01","last":"2024-04-01","end":"2025-03-31"},{"id":"1600983-0d23cabca8","kind":"annual","source":null,"discloses":"ai_harm","mit":["7.3"],"primary":"7.3","status":"materialised","harm":["Physical (injury)","Economic/Property"],"layers":["capability"],"whose":["own","others"],"relation":["within_purpose"],"misuse_by":[],"subjects":[{"name":"humans","type":"Group of persons"}],"text":"Nonetheless, real-life environments, especially those in crowded areas, are unpredictable and situations have in the past arisen and may in the future arise in which the ASRs may not perform as intended. Infrequent, but highly publicized incidents of autonomous vehicle and human interactions, including involving our ASRs, have focused consumer attention on the safety of our and other systems. We cannot assure you that a collision, including with property or with humans, will not occur.","ev":{"status":"Infrequent, but highly publicized incidents of autonomous vehicle and human interactions, including involving our ASRs","mit:7.3":"situations have in the past arisen and may in the future arise in which the ASRs may not perform as intended","harm:Physical (injury)":"We cannot assure you that a collision, including with property or with humans, will not occur","harm:Economic/Property":"collision, including with property","layer:capability":"situations have in the past arisen and may in the future arise in which the ASRs may not perform as intended","whose:own":"including involving our ASRs","whose:others":"Infrequent, but highly publicized incidents of autonomous vehicle and human interactions","relation:within_purpose":"situations have in the past arisen and may in the future arise in which the ASRs may not perform as intended"},"rev":null,"harm_quote":"situations have in the past arisen and may in the future arise in which the ASRs may not perform as intended","status_quote":"Infrequent, but highly publicized incidents of autonomous vehicle and human interactions, including involving our ASRs","reports":["0001410578-24-000417","0001558370-25-004171"],"forms":{"10-K":2},"first":"2024-04-01","last":"2025-03-31","end":"2026-03-27"},{"id":"1600983-82e857777a","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"On October 12, 2023, the UK Extension to the DPF came into effect (as approved by the UK Government), as a data transfer mechanism from the UK to U.S. entities self-certified under the DPF. As we continue to expand into other foreign countries and jurisdictions, we may be subject to additional laws and regulations that may affect how we conduct business. ​ The regulatory framework for AI is rapidly evolving as many federal, state and foreign government bodies and agencies have introduced or are currently considering additional laws and regulations. Additionally, existing laws and regulations may be interpreted in ways that would affect the operation of our AI technologies, or could be rescinded or amended as new administrations take differing approaches to evolving AI Technologies. As a result, implementation standards and enforcement practices are likely to remain uncertain for the foreseeable future, and we cannot yet determine the impact future laws, regulations, standards, or market perception of their requirements may have on our business and may not always be able to anticipate how to respond to these laws or regulations. ​ Already, certain existing legal regimes (e.g., relating to data privacy) regulate certain aspects of AI, and new laws regulating AI either entered or are expected to enter into force in the United States and the EU in 2025. In the United States, the Trump administration has rescinded an executive order relating to AI Technologies that was previously implemented by the Biden administration. The Trump administration may continue to rescind other existing federal orders and/or administrative policies relating to AI Technologies, or may implement new executive orders and/or other rule making relating to AI Technologies in the future. Any such changes at the federal level could require us to expend significant resources to modify our products, services, or operations to ensure compliance or remain competitive.. Already, agencies such as the Department of Commerce and the FTC have issued proposed rules governing the use and development of AI. U.S. legislation related to AI has also been introduced at the federal level and is advancing at the state level. For example, the California Privacy Protection Agency is currently in the process of finalizing regulations under the CCPA regarding the use of automated decision-making. California also enacted seventeen new laws in 2024 that further regulate use of AI Technologies and provide consumers with additional protections around companies’ use of AI Technologies, such as requiring companies to disclose certain uses of generative AI. Other states have also passed AI-focused legislation, such as Colorado’s Artificial Intelligence Act, which will require developers and deployers of “high-risk” AI systems to implement certain safeguards against algorithmic discrimination, and Utah’s Artificial Intelligence Policy Act, which establishes disclosure requirements and accountability measures for the use of generative AI in certain consumer interactions. Such additional regulations may impact our ability to develop, use and commercialize AI technologies in the future. 20 Table of Contents In Europe, on August 1, 2024, the EU Artificial Intelligence Act (the “EU AI Act”) entered into force, and establishes a comprehensive, risk-based governance framework for AI in the EU market. The majority of the substantive requirements will apply from August 2, 2026. The EU AI Act applies to companies that develop, use and/or provide AI in the EU and – depending on the AI use case – includes requirements around transparency, conformity assessments and monitoring, risk assessments, human oversight, security, accuracy, general purpose AI and foundation models, and fines for breach of up to 7% of worldwide annual turnover. In addition, the revised EU Product Liability Directive came into force in December 2024, to be implemented into EU member state national law by December 2026. This Directive extends the EU’s existing strict product liability regime to AI Technologies and AI-enabled products, and facilitates civil claims in respect of harm caused by AI. Once fully applicable, the EU AI Act and the EU Product Liability Directive will have a material impact on the way AI is regulated in the EU. Further, in Europe we are subject to GDPR, which regulates our use of personal data for automated decision making including individual profiling that results in a legal or similarly significant effect on an individual, and provides rights to individuals in respect of that automated decision making. Recent case law from the CJEU has taken an expansive view of the scope of the GDPR’s requirements around automated decision making and introduced uncertainty in the interpretation of these rules. Specifically, the CJEU has expanded the scope for automated decision making under the GDPR by finding that automated decision-making activities can fall within the GDPR’s restrictions on those activities even if the required legal or similarly significant effect for the individual is carried out by a third party. The EU AI Act, and developing interpretation and application of the GDPR in respect of automated decision making, together with developing guidance and/or decisions in this area, may affect our use of AI and our ability to provide, improve or commercialize our services, require additional compliance measures and changes to our operations and processes, result in increased compliance costs and potential increases in civil claims against us, and could adversely affect our business, operations and financial condition. ​ It is possible that further new laws and regulations will be adopted in the United States and in other non-U.S. jurisdictions, or that existing laws and regulations, including competition and antitrust laws, may be interpreted in ways that would limit our ability to use AI for our business, or require us to change the way we use AI in a manner that negatively affects the performance of our products, services, and business and the way in which we use AI. We may need to expend resources to adjust our products or services in certain jurisdictions if the laws, regulations, or decisions are not consistent across jurisdictions. Further, the cost to comply with such laws, regulations, or decisions and/or guidance interpreting existing laws, could be significant and would increase our operating expenses (such as by imposing additional reporting obligations regarding our use of AI). Such an increase in operating expenses, as well as any actual or perceived failure to comply with such laws and regulations, could adversely affect our business, financial condition and results of operations. ​ Although we work to comply with applicable laws, regulations and standards, our contractual obligations and other legal obligations, these requirements are evolving and may be modified, interpreted and applied in an inconsistent manner from one jurisdiction to another, and may conflict with one another or other legal obligations with which we must comply.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001558370-25-004171"],"forms":{"10-K":1},"first":"2025-03-31","last":"2025-03-31","end":"2026-03-27"},{"id":"1600983-d547620e04","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"On October 12, 2023, the UK Extension to the DPF came into effect (as approved by the UK Government), as a data transfer mechanism from the UK to U.S. entities self-certified under the DPF. As we continue to expand into other foreign countries and jurisdictions, we may be subject to additional laws and regulations that may affect how we conduct business. ​ The regulatory framework for AI is rapidly evolving as many federal, state and foreign government bodies and agencies have introduced or are currently considering additional laws and regulations. Additionally, existing laws and regulations may be interpreted in ways that would affect the operation of our AI technologies, or could be rescinded or amended as new administrations take differing approaches to evolving AI Technologies. As a result, implementation standards and enforcement practices are likely to remain uncertain for the foreseeable future, and we cannot yet determine the impact future laws, regulations, standards, or market perception of their requirements may have on our business and may not always be able to anticipate how to respond to these laws or regulations. ​ Already, certain existing legal regimes (e.g., relating to data privacy) regulate certain aspects of AI, and new laws regulating AI either entered or are expected to enter into force in the United States and the EU in 2025. Federal and state policymakers in the United States continue to evaluate regulatory approaches to AI technologies, including through executive actions, agency rulemaking, and legislation. Regulatory priorities and enforcement approaches may continue to shift across administrations. Any such changes at the federal level could require us to expend significant resources to modify our products, services, or operations to ensure compliance or remain competitive. Already, agencies such as the Department of Commerce and the FTC have issued proposed rules governing the use and development of AI. U.S. legislation related to AI has also been introduced at the federal level and is advancing at the state level. For example, the California Privacy Protection Agency is currently in the process of finalizing regulations under the CCPA regarding the use of automated decision-making. California also enacted seventeen new laws in 2024 that further regulate use of AI Technologies and provide consumers with additional protections around companies’ use of AI Technologies, such as requiring companies to disclose certain uses of generative AI. Other states have also passed AI-focused legislation, such as Colorado’s Artificial Intelligence Act, which will require developers and deployers of “high-risk” AI systems to implement certain safeguards against algorithmic discrimination, and Utah’s Artificial Intelligence Policy Act, which establishes disclosure requirements and accountability measures for the use of generative AI in certain consumer interactions. Such additional regulations may impact our ability to develop, use and commercialize AI technologies in the future. 22 Table of Contents In Europe, on August 1, 2024, the EU Artificial Intelligence Act (the “EU AI Act”) entered into force, and establishes a comprehensive, risk-based governance framework for AI in the EU market. The majority of the substantive requirements will apply from August 2, 2026. The EU AI Act applies to companies that develop, use and/or provide AI in the EU and – depending on the AI use case – includes requirements around transparency, conformity assessments and monitoring, risk assessments, human oversight, security, accuracy, general purpose AI and foundation models, and fines for breach of up to 7% of worldwide annual turnover. In addition, the revised EU Product Liability Directive came into force in December 2024, to be implemented into EU member state national law by December 2026. This Directive extends the EU’s existing strict product liability regime to AI Technologies and AI-enabled products, and facilitates civil claims in respect of harm caused by AI. Once fully applicable, the EU AI Act and the EU Product Liability Directive will have a material impact on the way AI is regulated in the EU. Further, in Europe we are subject to GDPR, which regulates our use of personal data for automated decision making including individual profiling that results in a legal or similarly significant effect on an individual, and provides rights to individuals in respect of that automated decision making. Recent case law from the CJEU has taken an expansive view of the scope of the GDPR’s requirements around automated decision making and introduced uncertainty in the interpretation of these rules. Specifically, the CJEU has expanded the scope for automated decision making under the GDPR by finding that automated decision-making activities can fall within the GDPR’s restrictions on those activities even if the required legal or similarly significant effect for the individual is carried out by a third party. The EU AI Act, and developing interpretation and application of the GDPR in respect of automated decision making, together with developing guidance and/or decisions in this area, may affect our use of AI and our ability to provide, improve or commercialize our services, require additional compliance measures and changes to our operations and processes, result in increased compliance costs and potential increases in civil claims against us, and could adversely affect our business, operations and financial condition. ​ It is possible that further new laws and regulations will be adopted in the United States and in other non-U.S. jurisdictions, or that existing laws and regulations, including competition and antitrust laws, may be interpreted in ways that would limit our ability to use AI for our business, or require us to change the way we use AI in a manner that negatively affects the performance of our products, services, and business and the way in which we use AI. We may need to expend resources to adjust our products or services in certain jurisdictions if the laws, regulations, or decisions are not consistent across jurisdictions. Further, the cost to comply with such laws, regulations, or decisions and/or guidance interpreting existing laws, could be significant and would increase our operating expenses (such as by imposing additional reporting obligations regarding our use of AI). Such an increase in operating expenses, as well as any actual or perceived failure to comply with such laws and regulations, could adversely affect our business, financial condition and results of operations. ​ Although we work to comply with applicable laws, regulations and standards, our contractual obligations and other legal obligations, these requirements are evolving and may be modified, interpreted and applied in an inconsistent manner from one jurisdiction to another, and may conflict with one another or other legal obligations with which we must comply.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-26-036240"],"forms":{"10-K":1},"first":"2026-03-27","last":"2026-03-27","end":null},{"id":"1600983-dc092b8b75","kind":"annual","source":null,"discloses":"ai_harm","mit":["7.3"],"primary":"7.3","status":"materialised","harm":["Physical (injury)","Economic/Property"],"layers":["capability"],"whose":["own","general"],"relation":["within_purpose"],"misuse_by":[],"subjects":[{"name":"humans","type":"Other"}],"text":"Nonetheless, real-life environments, especially those in crowded areas, are unpredictable and situations have in the past arisen and may in the future arise in which the ASRs may not perform as intended. Incidents 24 Table of Contents involving autonomous systems, including those involving third parties, have received public attention. We cannot assure you that a collision, including with property or with humans, will not occur.","ev":{"status":"situations have in the past arisen and may in the future arise in which the ASRs may not perform as intended","mit:7.3":"situations have in the past arisen and may in the future arise in which the ASRs may not perform as intended","layer:capability":"situations have in the past arisen and may in the future arise in which the ASRs may not perform as intended","whose:own":"situations have in the past arisen and may in the future arise in which the ASRs may not perform as intended","relation:within_purpose":"situations have in the past arisen and may in the future arise in which the ASRs may not perform as intended","harm:Physical (injury)":"We cannot assure you that a collision, including with property or with humans, will not occur.","harm:Economic/Property":"We cannot assure you that a collision, including with property or with humans, will not occur.","whose:general":"especially those in crowded areas"},"rev":null,"harm_quote":"situations have in the past arisen and may in the future arise in which the ASRs may not perform as intended","status_quote":"situations have in the past arisen and may in the future arise in which the ASRs may not perform as intended","reports":["0001104659-26-036240"],"forms":{"10-K":1},"first":"2026-03-27","last":"2026-03-27","end":null},{"id":"1600983-ec0683b37c","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"In addition, the publication of misinformation may also result in lawsuits, the uncertainty 30 Table of Contents and expense of which could adversely impact our business, financial condition, and reputation. There are no assurances that we will not face short sellers’ efforts or similar tactics in the future, and the market price of our Class A Common Stock may decline as a result of their actions. ​ Risks Related to the Event Risk Acquisition ​ The Event Risk Acquisition may not achieve its intended results. ​ Although we currently anticipate that the Event Risk Acquisition will accelerate our long-term strategy to operate a fully integrated autonomous security platform, we may fail to realize the anticipated benefits of the Event Risk Acquisition, encounter additional transaction and integration-related costs, or be affected by other factors that impact our ability to successfully combine Event Risk’s security guarding services into the Knightscope platform, any of which could decrease or delay the expected accretion and contribute to a decrease in the price of our common stock. ​ We completed the Event Risk Acquisition anticipating various benefits to the Company, including integrating Event Risk’s licensed response services with Knightscope’s autonomous machines and AI-driven orchestration software to build a unified operating model designed to deliver deterrence, detection and response as one coordinated system. Achievement of the anticipated benefits is subject to a number of uncertainties, including our ability to effectively integrate the acquired business, which may be complex, costly, and time-consuming.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-26-036240"],"forms":{"10-K":1},"first":"2026-03-27","last":"2026-03-27","end":null}],"k8":[{"id":"1600983-8k-e183baf699","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"(“ASI”) since November 2000. ASI was founded in 2000 as a spinoff from Utah State University and provides technology to create fully autonomous vehicles by retrofitting existing equipment. In his role at ASI, Mr.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-24-025214"],"forms":{"8-K":1},"first":"2024-02-20","last":"2024-02-20","end":null},{"id":"1600983-8k-431b074841","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Mr. Torrie has taught at Utah State University and is a frequent keynote speaker and trainer on the topics of artificial intelligence, machine learning, autonomous vehicles, industrial robotics, and leadership. Mr.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-24-025214"],"forms":{"8-K":1},"first":"2024-02-20","last":"2024-02-20","end":null},{"id":"1600983-8k-74d032d005","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"The Board believes Mr. Torrie is qualified to serve on the Board due to his significant experience in leadership and with technology, autonomous vehicles, and robotics. Resignation of Directors On the Commencement Date, each of Patricia Howell, Linda Keene Solomon, and Patricia L.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-24-025214"],"forms":{"8-K":1},"first":"2024-02-20","last":"2024-02-20","end":null},{"id":"1600983-8k-151024e69e","kind":"8-K","source":null,"discloses":"ai_harm","mit":["7.3"],"primary":"7.3","status":"materialised","harm":["Physical (injury)"],"layers":["capability"],"whose":["own"],"relation":["within_purpose"],"misuse_by":[],"subjects":[{"name":"toddler","type":"Individual"}],"text":"This incident proves that Knightscope’s robots, can't even follow \"Asimov's first law of robotics,\" which prioritizes the protection of human life above anything else. As competition in the robotics industry grows, and with advancements in AI, the achievement of full autonomy becomes more accessible, posing challenges for Knightscope and the competition it may face. The mother of the toddler involved in the incident commented, \"The robot hit my son's head, and he fell down facing the floor, but the robot didn't stop, it just kept moving forward.\" The parents of the toddler also stated that the robot ran over his right foot, causing swelling, and he suffered a scrape on his leg.","ev":{"status":"The robot hit my son's head, and he fell down facing the floor, but the robot didn't stop","mit:7.3":"The robot hit my son's head, and he fell down facing the floor, but the robot didn't stop, it just kept moving forward.","layer:capability":"The robot hit my son's head, and he fell down facing the floor, but the robot didn't stop, it just kept moving forward.","harm:Physical (injury)":"the robot ran over his right foot, causing swelling, and he suffered a scrape on his leg","whose:own":"This incident proves that Knightscope","relation:within_purpose":"This incident proves that Knightscope"},"rev":null,"harm_quote":"The robot hit my son's head, and he fell down facing the floor, but the robot didn't stop, it just kept moving forward.","status_quote":"The robot hit my son's head, and he fell down facing the floor, but the robot didn't stop","reports":["0001104659-24-029611"],"forms":{"8-K":1},"first":"2024-03-01","last":"2024-03-01","end":null},{"id":"1600983-8k-1ee7b2de0b","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"The Roadshow will be open from 10:00am to 2:00pm Eastern Time. The Robot Roadshow is an engaging experiential event, allowing potential clients and the general public to participate in expert-led demonstrations in a climate controlled, space-age \"'pod\" where attendees may experience the self-driving, electric technologies that are already helping protect the places people live, work, study and visit from Hawaii to Texas to Pennsylvania. Visitors will be able to interact directly with Autonomous Security Robots, test a blue light emergency phone, and see the Knightscope Security Operations Center Watch a brief video of the Bohor Roadshow at the Tesla Takeover here The Robot Roadshow is free to attend for everyone. Those wishing to schedule a time to get one-on-one attention may book a P9d visit here. Case 1:23-cv-11050 Document 1-4 Filed 12/20/23 Page 10 of 11 Fun Fact: Knightscope was the first AD to show when searching in google, terms like \"What stock should I buy\" \"Best AI Stock\" Pressreach Disclaimer: Opinion, Not Financial Advice The information provided here is solely for informational purposes and represents our personal opinions and viewpoints. It should not be considered as financial advice or recommendations for any specific course of action.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-24-029611"],"forms":{"8-K":1},"first":"2024-03-01","last":"2024-03-01","end":null},{"id":"1600983-8k-7079f51e56","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Our long-term strategy is to network millions of autonomous machines, combining both current and future technologies, offering a multi-faceted and comprehensive approach to public safety. Enhancing technological capabilities by an order of magnitude will improve efficiency and response times, leverage the power of AI for advanced autonomous cooperation, all while providing a scalable, cost-effective solution that can adapt to future challenges against those seeking to do harm to everyday Americans. 4 Source: (1) FBI Crime Clock and 2006 U.S. Senate hearings. This information is supplied from public sources we believe to be reliable, but we cannot guarantee their accuracy. Opportunity Public Safety is ripe for disruption by Artificial Intelligence and Robotics. Knightscope represents an opportunity to build a $30 billion market cap company that is analogous to the building of an all-new defense contractor but instead of focusing exclusively on the battlefield, we are focused on deploying groundbreaking technologies that we believe have the potential to be used by the U.S.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-24-034500"],"forms":{"8-K":1},"first":"2024-03-14","last":"2024-03-14","end":null},{"id":"1600983-8k-51161d7a3d","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Crime We believe the 2.5 million law enforcement professionals and security guards, without the proper tools and technology, are woefully inadequate to safeguard 332 million Americans across 50 states. This is evidenced by the fact that crime has a $2+ trillion negative economic impact on the U.S. annually and a violent crime occurs every 26 seconds while a property crime occurs every 4 seconds.1 Technology Knightscope’s unique technology combining autonomy, robotics, AI and EV capabilities has been proven to be effective in crime fighting with nearly 3 million hours of operation in real world conditions across every time zone in America, through multiple winters and summers. Machines-in-Network We have nearly 10,000 machines-in-network today and long-term we are targeting to put over 1 million machines-in-network to assist the 2.5 million law enforcement professionals and security guards with unprecedented capabilities at their fingertips – near superhuman capabilities.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-24-034500"],"forms":{"8-K":1},"first":"2024-03-14","last":"2024-03-14","end":null},{"id":"1600983-8k-d5c9249ee3","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Federal Government after an exhaustive 3-year cyber security review process uniquely positions Knightscope in the marketplace with a clear first mover advantage. Additionally, a unified AI driven software platform that brings together both data and autonomous cooperation from a plethora of machines and systems will provide unparalleled situational awareness, analytics, prediction and evidentiary capabilities – and a significant competitive advantage. DISRUPTION BY A.I. 5 CORE TECHNOLOGY Artificial Intelligence Knightscope has utilized AI nationwide since its founding in 2013 and well before the recent mainstream excitement. We utilize it to autonomously operate in highly dynamic outdoor and indoor environments, to autonomously recharge as well as for automated detections of people, faces, and license plates. We believe artificial intelligence is only going to accelerate our portfolio of machines to be able to “see, feel, hear, smell, speak – and cooperate”. ASR Portfolio Our Autonomous Security Robots generate over 90 terabytes of data a year and we put that into a digestible format for a human to utilize with our Knightscope Security Operations Center (KSOC) user interface software application.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-24-034500"],"forms":{"8-K":1},"first":"2024-03-14","last":"2024-03-14","end":null},{"id":"1600983-8k-1b2fe37c94","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Additionally, we recently added an integrated or stand-alone option for hyper accurate Automated Gunshot Detection (AGD). Portfolio Technology Status ASR KSOC User Interface Production K1 Hemisphere Production K1 Tower Production K3 Indoor Production K5 Outdoor Production K1B KEMS User Interface Production K1 Blue Light Tower Production K1 Blue Light E-Phone Production K1 Call Box Production K1 Retrofit Kit Production DETECTIONS Knightscope+ Remote Monitoring Production Automated Gunshot Detection Production 6 FUTURE TECHNOLOGY We Envision an All New AI Mission Control Software Autonomy Platform to Predict and Prevent Crime Robots Will Be Everywhere We believe the technology landscape is going to change dramatically over the coming years for public safety and the software tools used today will be replaced. A game changing opportunity exists to redefine the sector by developing an all-new AI driven software platform monitoring and managing a network of autonomous security robots, blue light emergency towers, e-phones, call boxes, aerial drones, autonomous patrol vehicles, quadrupeds, humanoids and other future technologies, enabling machines to observe, learn, reason and act – in concert or solo - to address real world public safety events in real time. Autonomous Mission Planning In the event of an actual or forecasted incident, the AI could propose alternative response plans, including the closest machines and humans for rapid deployment, optimal paths for intervention, and necessary resources, coordinating emergency services and alerting the public as needed. Utilizing robot swarming techniques will enable cross-machine autonomous cooperation. Forecast AI algorithms could analyze data streams from various machines to identify potential threats or unusual behaviors. The system could use historical data and machine learning to predict potential public safety incidents allowing preemptive action including optimal resource allocation of machines and humans. Operations Real time mission status as well as health of machines-in-network across all autonomous machines including real time data feeds, status, configuration, reporting and AI driven preventative maintenance. Integrated Neighborhood Watch Cross-platform communication integrating with external systems for sharing of critical information and coordinating responses.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-24-034500"],"forms":{"8-K":1},"first":"2024-03-14","last":"2024-03-14","end":null},{"id":"1600983-8k-85cc8991cb","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Winner of Leadership ABIE Award for Women in Technology and Silicon Valley Business Journal’s Woman of Influence Award Former Deloitte software engineering leader with 15+ years of experience in enterprise, artificial intelligence and machine learning Aaron J Lehnhardt, EVP and Chief Design Officer 20+ years in two- and three-dimensional product and industrial design","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-24-034500"],"forms":{"8-K":1},"first":"2024-03-14","last":"2024-03-14","end":null},{"id":"1600983-8k-a3cf2e93e1","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Torrie has taught at Utah State University and worked on multiple NASA Space Shuttle payloads. His autonomous vehicle development efforts started 27 years ago and led to the spinout of Autonomous Solutions, Inc. (“ASI”) in 2000 to make driverless vehicles a reality in industries like agriculture, mining, construction, and logistics. As ASI CEO and Chairman of its board of directors, Mr. Torrie has piloted robotic development partnerships with some of the largest vehicle manufacturers in the world, such as John Deere, Case, New Holland, Ford, Chrysler, Komatsu, Doosan and Toyota. He is also an invited keynote speaker and trainer around the world on the topics of AI, Machine Learning, Autonomous Vehicles, Industrial Robotics and Leadership. Mr.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-24-034500"],"forms":{"8-K":1},"first":"2024-03-14","last":"2024-03-14","end":null},{"id":"1600983-8k-79207eeffd","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"We are reducing our fixed costs with a streamlined management team and a reduction in our facility footprint nationwide from 13 to 1 over time. Technology We seek to ramp up production of both the all-new K1 Hemisphere and the 5th generation K5 while continuing development on our all-new K7 ASR and kicking off development on our AI-driven Mission Control software application. Our mission is to make the United States of America the safest country in the world.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-24-034500"],"forms":{"8-K":1},"first":"2024-03-14","last":"2024-03-14","end":null},{"id":"1600983-8k-d2e34dd83b","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"EX-99.1 2 tm2410412d1_ex99-1.htm EXHIBIT 99.1 Exhibit 99.1 Knightscope News Release April 2, 2024 4:00AM PT Knightscope Announces Significant Financial Milestones Town Hall with CEO and CFO Scheduled for Tonight Technology Innovator Continues Executing on Roadmap to Profitable Growth MOUNTAIN VIEW, Calif., April 2, 2024 -- Knightscope, Inc. [Nasdaq: KSCP] (“Knightscope” or the “Company”), an innovator in robotics and artificial intelligence (“AI”) technologies focused on public safety, today announced its financial results for the fiscal year ended December 31, 2023, marking significant progress towards its goals of profitability and operational efficiency. Key 2023 Financial Highlights Substantial Revenue Increase Knightscope reported $12.8 million in revenue for 2023, which marks a 128% increase from the previous year.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-24-042212"],"forms":{"8-K":1},"first":"2024-04-02","last":"2024-04-02","end":null},{"id":"1600983-8k-9fc777bb78","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"EX-99.1 6 tm2429235d1_ex99-1.htm EXHIBIT 99.1 Exhibit 99.1 Knightscope News Release November 21, 2024 1:15PM PT Knightscope Announces Proposed Public Offering MOUNTAIN VIEW, Calif., November 21, 2024 -- Knightscope, Inc. [Nasdaq: KSCP] (“Knightscope” or the “Company”), an innovator in robotics and artificial intelligence (“AI”) technologies focused on public safety, today announces that it is proposing to offer and sell, subject to market conditions, shares of its Class A common stock (or pre-funded warrants in lieu thereof) in an underwritten public offering. Knightscope expects to grant the underwriter a 30-day option to purchase up to an additional 15% of the number of shares of Class A common stock and pre-funded warrants to be offered in this public offering on the same terms and conditions.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-24-122131"],"forms":{"8-K":1},"first":"2024-11-22","last":"2024-11-22","end":null},{"id":"1600983-8k-48271e8016","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"EX-99.2 7 tm2429235d1_ex99-2.htm EXHIBIT 99.2 Exhibit 99.2 Knightscope News Release November 21, 2024 5:01PM PT Knightscope Announces Pricing of $12.1 Million Public Offering MOUNTAIN VIEW, Calif., November 21, 2024 -- Knightscope, Inc. [Nasdaq: KSCP] (“Knightscope” or the “Company”), an innovator in robotics and artificial intelligence (“AI”) technologies focused on public safety, today announces the pricing of an underwritten public offering of 1,210,000 shares of its Class A common stock (or pre-funded warrants in lieu thereof) at a public offering price of $10.00 per share. The pre-funded warrants will be immediately exercisable and may be exercised at any time until all of the pre-funded warrants are exercised in full.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-24-122131"],"forms":{"8-K":1},"first":"2024-11-22","last":"2024-11-22","end":null},{"id":"1600983-8k-4040ebc1fd","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"See Appendix. Broad Client Base LIVE Apartments Condominiums Homeowner Associations Mixed Use Subdivisions WORK Corporate Campuses Commercial Real Estate Government Industrial Logistics Facilities Manufacturing Plants STUDY K-12 Schools Universities Training Centers CRIME can occur in all the places that are important to people Knightscope technologies operate 24/7/365 to PROTECT these places VISIT Airports Casinos Hospitals Hotels Parking Parks Rail Retail Storage Diversified Business Model BLENDED model with strong recurring revenue and transactional sales Ensures stability and growth potential RECURRING REVENUE ASR Machine-as-a-Service (MaaS) Knightscope Network Operations Center (KNOC) Risk & Threat Exposure (RTX) Knightscope Emergency Management System (KEMS) ECD Full-Service Maintenance (FSM) TRANSACTIONAL REVENUE Blue Light Towers Blue Light Emergency Phones Call Boxes Retrofit Kits HIGH MARGINS EXPANSION POTENTIAL We Protect the Places You LIVE WORK STUDY VISIT OUR GROWTH STRATEGY MAKE AMERICA THE SAFEST COUNTRY IN THE WORLD Moonshot FUTURE AI DRIVEN Public Safety Infrastructure is Advanced and Intelligent 1 million law enforcement professionals 1.5 million security guards 85 million cameras 300,000law enforcement vehicles EXISTING Public Safety Infrastructure is Archaic and Fragmented ROBOTS WILL BE EVERYWHERE. Additional 1 million machines-in-network that can see, feel, hear, smell, speak and autonomously cooperate to support the 2.5 million human officers and guards 24/7/365 Key Growth Drivers U.S.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-25-022699"],"forms":{"8-K":1},"first":"2025-03-12","last":"2025-03-12","end":null},{"id":"1600983-8k-73a7ebf058","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Founder and Chief Operating Officer of GreenLeaf, which became the world's 2nd largest automotive recycler (now NASDAQ: LKQ) Mercedes Soria EVP and CIO | CISO Award winning former Deloitte software engineering leader with deep experience in enterprise, artificial intelligence and startups Former Ford Motor Company senior designer, digital design expert and Alias 3D instructor at College for Creative Studies","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-25-022699"],"forms":{"8-K":1},"first":"2025-03-12","last":"2025-03-12","end":null},{"id":"1600983-8k-cd48b0341b","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Allied Market Research – Emergency Communication Systems Market Growth Analysis, 2023–2030 (January 2024) Frost & Sullivan – AI-Driven Security & Surveillance Trends, 2024 (February 2024) DHS & FBI Annual Reports – U.S. Public & Private Sector Security Spending Estimates (2023) National Institute of Standards and Technology (NIST) – AI & Robotics in Public Safety: Market Growth Report (2023) Homeland Security Research Corp. – Critical Infrastructure Protection & Perimeter Security Market Outlook, 2023-2028 (October 2023)","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-25-022699"],"forms":{"8-K":1},"first":"2025-03-12","last":"2025-03-12","end":null},{"id":"1600983-8k-e5c7871f0c","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"EX-99.1 4 tm2510385d3_ex99-1.htm EXHIBIT 99.1 Exhibit 99.1 Knightscope Announces $1.7 Million Registered Direct Offering of Common Stock MOUNTAIN VIEW, Calif., March 28, 2025--(BUSINESS WIRE)--Knightscope, Inc. (NASDAQ: KSCP) (the “Company”), a leader in developing autonomous security robots and artificial intelligence technologies, today announced that it has entered into a definitive agreement for the purchase and sale of an aggregate of 625,000 shares of the Company’s Class A common stock at a purchase price of $2.75 per share in a registered direct offering. The offering is expected to close on or about March 31, 2025, subject to the satisfaction of customary closing conditions.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-25-029917"],"forms":{"8-K":1},"first":"2025-03-31","last":"2025-03-31","end":null},{"id":"1600983-8k-5728a8a836","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"This press release shall not constitute an offer to sell or a solicitation of an offer to buy these securities, nor shall there be any sale of these securities in any state or jurisdiction in which such offer, solicitation or sale would be unlawful prior to the registration or qualification under the securities laws of any such state or jurisdiction. About Knightscope Knightscope is transforming public safety with cutting-edge robotics and AI technologies. From autonomous security robots to advanced detection systems, Knightscope is committed to building safer communities where you live, work, study and visit.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-25-029917"],"forms":{"8-K":1},"first":"2025-03-31","last":"2025-03-31","end":null},{"id":"1600983-8k-fa6d18df3e","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"EX-99.1 2 tm2512231d1_ex99-1.htm EXHIBIT 99.1 Exhibit 99.1 Knightscope Secures New 33,000 Sq Ft Silicon Valley Headquarters to Power Next Phase of Growth as a New Era Begins Thu, 10 Apr 2025 09:35:00 -0400 | Business Wire Content Section Knightscope, Inc. (NASDAQ: KSCP), a leader in AI-powered autonomous public safety and emergency communication technologies, today announced the signing of a lease for its new 33,355-square-foot corporate headquarters at 305 North Mathilda Avenue in Sunnyvale, California. Timed to mark the Company's 12th anniversary since its founding in 2013, this expansion signifies a bold step forward in Knightscope's mission to make America the safest country in the world.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-25-034664"],"forms":{"8-K":1},"first":"2025-04-14","last":"2025-04-14","end":null},{"id":"1600983-8k-09079a4df2","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"The Sunnyvale facility will serve as a hub for innovation for national deployment of Knightscope's cutting-edge technologies for both private sector and federal clients – while creating new engineering and manufacturing jobs in America. \"As we commemorate twelve years of relentless innovation and perseverance, securing this new headquarters is a major milestone for the entire Knightscope team,\" said William Santana Li, Chairman and CEO. \"This facility will serve as the launchpad for our next phase of growth, giving us the space and infrastructure needed to deliver even more powerful solutions to our clients across the country.\" By centralizing operations in a significantly larger facility, Knightscope is preparing to increase production capacity for its Autonomous Security Robots (ASR) and Emergency Communication Devices (ECD), improve internal collaboration, and streamline nationwide deployment of its technologies – including development and manufacturing of the future K7 ASR and K1 Super Tower in 2026. About Knightscope Knightscope is transforming public safety with cutting-edge robotics and AI technologies. From autonomous security robots to advanced detection systems, Knightscope is committed to building safer communities where you live, work, study and visit.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-25-034664"],"forms":{"8-K":1},"first":"2025-04-14","last":"2025-04-14","end":null},{"id":"1600983-8k-714604420a","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Historically, physical security has been delivered through fragmented components -- guards, cameras, monitoring centers, and patrol services operating independently. Knightscope’s strategy is to integrate: · Autonomous Security Robots and Emergency Communication Devices (hardware); · AI-driven event detection and orchestration software; and · Licensed security personnel and response services into a coordinated operating model designed to deliver detection, deterrence, verification, and response as a unified outcome. Knightscope believes that security buyers purchase improved outcomes rather than individual devices or labor hours. By owning the human layer alongside its technology platform, Knightscope can deploy its hardware and AI software within a managed service structure that supports enterprise accountability and scalable deployment. The Company expects this structure to: · Accelerate adoption of its robotics and sensing technologies; · Enable participation in security contracts requiring licensed guarding providers; · Increase multi-site deployment opportunities; and · Improve customer retention through integrated service delivery.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-26-022476"],"forms":{"8-K":1},"first":"2026-03-03","last":"2026-03-03","end":null},{"id":"1600983-8k-1b6e53a534","kind":"8-K","source":null,"discloses":"ai_harm","mit":["6.2"],"primary":"6.2","status":"hypothetical","harm":["Economic/Property"],"layers":["systemic"],"whose":["own"],"relation":["within_purpose"],"misuse_by":[],"subjects":[],"text":"Knightscope intends to integrate Event Risk personnel and operations into its broader Autonomous Security Force strategy, whereby technology-enabled supervision allows human operators to oversee multiple sites and respond to verified events. Long-Term Operating Model Knightscope anticipates evolving the combined model over time through: · Increased hardware density per site; · AI-driven alert reduction and prioritization; · Technology-enabled supervision across multiple locations; and · Gradual automation of routine patrol functions, unfit or unsafe for a human. The Company believes this approach may shift the cost structure from labor-intensive deployments toward technology-enabled productivity over time.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-26-022476"],"forms":{"8-K":1},"first":"2026-03-03","last":"2026-03-03","end":null},{"id":"1600983-8k-838a7236b4","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"The Company believes this combination uniquely positions it to deliver end-to-end accountability across sensing, decision-making, and response. Knightscope’s AI software platform is designed to: · Fuse data from robots, sensors, and cameras; · Reduce false or unverified alerts; · Prioritize escalation pathways; and · Coordinate human verification and response. The Company believes that traditional guarding scales linearly with labor. Knightscope’s intended operating model utilizes technology to enable human oversight across multiple locations, potentially improving productivity relative to traditional models. Market Positioning Knightscope believes: · Technology-only vendors typically lack response capability and licensed guard infrastructure; and · Traditional guarding firms typically lack proprietary autonomous robotics and AI orchestration platforms. By integrating both, Knightscope intends to compete for security contracts requiring end-to-end delivery rather than component sales.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-26-022476"],"forms":{"8-K":1},"first":"2026-03-03","last":"2026-03-03","end":null},{"id":"1600983-8k-0c6d4ecd69","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"(NASDAQ: KSCP), the security technology company building the nation’s first Autonomous Security Force, today announced it has completed the acquisition of Event Risk LLC (“Event Risk”), a nationwide provider of armed and unarmed security guarding services and executive protection. Traditional guarding firms typically lack proprietary autonomous robotics and AI orchestration platforms, while technology-only vendors typically lack licensed physical response infrastructure. Knightscope now combines both as a managed service provider – not a collection of disconnected vendors lacking unified accountability. The result is a single contract and a single escalation owner accountable for outcomes. By consolidating autonomous systems, AI-driven command software, and licensed armed and unarmed response under one contract, Knightscope is repositioning physical security from a fragmented service model to an integrated managed service platform. This acquisition establishes the structural capability for Knightscope to contract as the licensed provider, deploy autonomous systems, monitor centrally, and execute response under one accountable operating structure. Event Risk has demonstrated consistent double-digit growth, strong client retention, disciplined leadership team, and established service relationships with Fortune 1000 companies, national brands, and high-profile individuals. It enters 2026 with significant contracted revenue, positive EBITDA, and expectations of continued double-digit growth, prior to any synergies. Knightscope believes integrating autonomous technology with licensed security operations strengthens the capabilities and market reach of both organizations. “This is a strategic move in building the Nation’s First Autonomous Security Force,” said William Santana Li, Chairman and CEO of Knightscope. “Security buyers are forced to purchase disconnected products and services today – but what they ultimately need is accountability and outcomes. By integrating licensed response services with autonomous machines and AI-driven orchestration software, we are building a unified operating model designed to deliver deterrence, detection, and response as one coordinated system.” Strategic Rationale Knightscope’s integrated operating model is built on three coordinated functions: visible autonomous presence to deter threats, AI-driven sensing to detect events, and licensed human response to verify and act. By aligning deterrence, detection, and response under a single accountable structure, the Company intends to deliver measurable security outcomes rather than fragmented services.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-26-022476"],"forms":{"8-K":1},"first":"2026-03-03","last":"2026-03-03","end":null},{"id":"1600983-8k-70b8608c2f","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"The acquisition of Event Risk enables Knightscope to participate in engagements where technology-only vendors are frequently disqualified prior to evaluation. Owning the Delivery Layer By integrating licensed response services with proprietary hardware and AI software, Knightscope intends to participate in a greater share of total contract value while increasing deployment density and recurring revenue across enterprise accounts. 1 Knightscope believes this integrated structure strengthens competitive positioning while creating expanded deployment opportunities across enterprise environments. Leadership and Integration Eric J.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-26-022476"],"forms":{"8-K":1},"first":"2026-03-03","last":"2026-03-03","end":null},{"id":"1600983-8k-cea5a4eee0","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Strategic Outlook Knightscope believes the U.S. physical security market represents an estimated $230 billion annual opportunity and that a vertically integrated delivery model is the strategic path to capture a greater share of that spend. By integrating licensed response services with proprietary hardware and AI-driven orchestration software, Knightscope believes this model is designed to enable scale without proportional increases in headcount, increasing deployment density and recurring revenue across enterprise accounts. “Security demands continue to increase while staffing constraints persist across the industry,” added Li. “The future of security is not human-only or machine-only – it is orchestrated. This acquisition strengthens our ability to deliver end-to-end accountability across sensing, decision-making, and response as we scale the Nation’s First Autonomous Security Force.” The Company plans to present the integrated security model at the GSX (Global Security Exchange) conference in Atlanta, Georgia later this year.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-26-022476"],"forms":{"8-K":1},"first":"2026-03-03","last":"2026-03-03","end":null},{"id":"1600983-8k-6bbd2a87a5","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Client interest in K7 deployment continues to grow, and the Company’s partnership with Carnegie Mellon University has its graduate robotics program working directly on autonomous patrol technology under the guidance of Knightscope’s engineering team. Signals platform underway: Significant work is underway on the Company’s all-new Signals platform, designed to orchestrate its autonomous robots, stationary devices, sensors, augmented security agents, and Mission Intelligence remote monitoring – an industry first that combines pioneering proprietary 3D digital twin technology with AI agents to eliminate blind spots and provide an industry-first, proof-of-work audit trail. Growth with discipline: The team cut assembly time for one of the Company’s product lines by almost 80%, restructured the field service network in Northern California and the Northeast region through local service provider relationships, insourced field services in Southern California to improve service while lowering delivery costs, significantly deepened the technical team, and recruited multiple senior executives with a track record of scaling companies. ​ ​","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-26-094868"],"forms":{"8-K":1},"first":"2026-08-12","last":"2026-08-12","end":null},{"id":"1600983-8k-599415a69f","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"The update comes on the heels of GSX 2026, the Global Security Exchange in Atlanta, where Knightscope officially launched the Autonomous Security Force (the “Force”). The Force combines autonomous machines, AI-driven software, and licensed security agents as one accountable operation with a single point of accountability for the client. Renewals are estimated to account for approximately $19.6 million, or 72%, of the total, reflecting existing clients electing to continue with Knightscope, and new business is estimated to account for approximately $7.5 million, or 28%.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-26-109484"],"forms":{"8-K":1},"first":"2026-09-22","last":"2026-09-22","end":null},{"id":"1600983-8k-34dc30e604","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"About Knightscope Knightscope is a security technology company building the nation’s first Autonomous Security Force. As a managed service provider, the Company delivers autonomous machines, AI-driven software, and licensed security agents as one accountable operation, under one contract, to help protect people, property, and critical infrastructure. Knightscope’s long-term mission is to make the United States of America the safest country in the world.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001104659-26-109484"],"forms":{"8-K":1},"first":"2026-09-22","last":"2026-09-22","end":null}]});
